import { effect, signal } from '@vorzelajs/core'

import { accessorOf, useId } from '~/hooks/index.ts'
import { cx } from '~/lib/cx.ts'
import { forwardRef } from '~/lib/types.ts'
import type { ChangeEvent, HTMLAttributes } from '~/lib/types.ts'
import { CircleAlert, CircleCheck } from './icons.tsx'
import { Label } from './label.tsx'
import styles from './textarea.module.scss'

export type TextareaProps = HTMLAttributes<HTMLTextAreaElement> & {
  label?: string
  hint?: string
  error?: string
  success?: string
  /** Show a live character count. Needs `maxLength` to be meaningful. */
  showCount?: boolean
  wrapClassName?: string
  value?: string | (() => string)
  defaultValue?: string | number
  required?: boolean
  disabled?: boolean
  rows?: number
  cols?: number
  maxLength?: number
  placeholder?: string
  name?: string
  onChange?: (event: ChangeEvent<HTMLTextAreaElement>) => void
}

export const Textarea = forwardRef<HTMLTextAreaElement, TextareaProps>(
  function Textarea(
    {
      label,
      hint,
      error,
      success,
      showCount = false,
      wrapClassName,
      id: idProp,
      className,
      required,
      disabled,
      rows = 4,
      maxLength,
      value: valueProp,
      defaultValue,
      onChange,
      ...props
    },
    ref,
  ) {
    const generatedId = useId('textarea')
    const id = idProp ?? generatedId
    const controlled =
      valueProp === undefined ? null : accessorOf<string>(valueProp)

    const initial = controlled
      ? controlled()
      : String(defaultValue ?? '')
    const [count, setCount] = signal(initial.length)

    // A controlled value can change without a DOM event (reset, server
    // refresh), so the counter follows the accessor.
    effect(() => {
      if (controlled) setCount(controlled().length)
    })

    const hasError = Boolean(error)
    const hasSuccess = Boolean(success) && !hasError
    const describedBy =
      [
        hint ? `${id}-hint` : null,
        hasError ? `${id}-error` : null,
        hasSuccess ? `${id}-success` : null,
      ]
        .filter(Boolean)
        .join(' ') || undefined

    const atLimit = (): boolean =>
      maxLength !== undefined && count() >= maxLength

    return (
      <div className={cx(styles.field, wrapClassName)}>
        {label ? (
          <Label
            htmlFor={id}
            required={required}
            hint={hint}
            hintId={`${id}-hint`}
          >
            {label}
          </Label>
        ) : null}

        <div
          className={cx(
            styles.shell,
            hasError ? styles.invalid : hasSuccess ? styles.valid : undefined,
            disabled && styles.disabled,
          )}
        >
          <textarea
            {...props}
            ref={ref}
            id={id}
            rows={rows}
            required={required}
            disabled={disabled}
            maxLength={maxLength}
            value={controlled ?? defaultValue}
            aria-invalid={hasError ? 'true' : undefined}
            aria-describedby={describedBy}
            className={cx(styles.control, className)}
            onChange={(event) => {
              setCount(
                (event.currentTarget as HTMLTextAreaElement).value.length,
              )
              onChange?.(event as ChangeEvent<HTMLTextAreaElement>)
            }}
          />

          {hasError ? (
            <span className={cx(styles.status, styles.statusError)}>
              <CircleAlert aria-hidden />
            </span>
          ) : hasSuccess ? (
            <span className={cx(styles.status, styles.statusSuccess)}>
              <CircleCheck aria-hidden />
            </span>
          ) : null}
        </div>

        {hasError || hasSuccess || (showCount && maxLength !== undefined) ? (
          <div className={styles.message}>
            {hasError ? (
              <p id={`${id}-error`} role="alert" className={styles.errorText}>
                {error}
              </p>
            ) : hasSuccess ? (
              <p id={`${id}-success`} className={styles.successText}>
                {success}
              </p>
            ) : null}

            {showCount && maxLength !== undefined ? (
              <p
                className={() =>
                  cx(styles.counter, atLimit() && styles.counterAtLimit)
                }
              >
                {() => `${count()} / ${maxLength}`}
              </p>
            ) : null}
          </div>
        ) : null}
      </div>
    )
  },
)

Textarea.displayName = 'Textarea'

@use 'styles' as vz;

.field {
  display: flex;
  flex-direction: column;
  gap: vz.space(1);
  min-width: 0;
}

.shell {
  position: relative;
  display: flex;
  border: 1px solid vz.color('border');
  border-radius: vz.radius('xl');
  background: vz.color('card');
  transition:
    border-color vz.duration('base') vz.ease('out'),
    box-shadow vz.duration('base') vz.ease('out'),
    background-color vz.duration('base') vz.ease('out');

  &:focus-within {
    border-color: vz.color('primary');
    box-shadow: 0 0 0 3px vz.color('primary', 0.18);
  }
}

.invalid {
  border-color: vz.color('destructive');

  &:focus-within {
    border-color: vz.color('destructive');
    box-shadow: 0 0 0 3px vz.color('destructive', 0.18);
  }
}

.valid {
  border-color: vz.color('success');

  &:focus-within {
    border-color: vz.color('success');
    box-shadow: 0 0 0 3px vz.color('success', 0.18);
  }
}

.disabled {
  background: vz.color('muted');
  opacity: 0.6;
  pointer-events: none;
}

.control {
  display: block;
  width: 100%;
  min-height: vz.space(20);
  padding: vz.space(3) vz.space(4);
  border: 0;
  background: transparent;
  color: inherit;
  font-size: vz.font-size('sm');
  line-height: 1.5;
  caret-color: vz.color('primary');
  resize: vertical;
  outline: none;

  @include vz.placeholder {
    color: vz.color('muted-foreground');
  }
}

.status {
  position: absolute;
  top: vz.space(3);
  right: vz.space(3);
  display: inline-flex;
  pointer-events: none;
  animation: vz-status-in 180ms vz.ease('spring') both;

  svg {
    @include vz.icon(4);
  }

  @include vz.motion-reduce {
    animation: none;
  }
}

@keyframes vz-status-in {
  from {
    opacity: 0;
    transform: scale(0.6);
  }

  to {
    opacity: 1;
    transform: none;
  }
}

.status-error {
  color: vz.color('destructive');
}

.status-success {
  color: vz.color('success');
}

.message {
  display: flex;
  align-items: center;
  gap: vz.space(3);
  min-height: 1rem;
  font-size: vz.font-size('xs');
}

.message p {
  margin: 0;
}

.error-text {
  color: vz.color('destructive');
}

.success-text {
  color: vz.color('success');
}

.counter {
  margin-left: auto;
  color: vz.color('muted-foreground');
  font-size: vz.font-size('xs');
  font-variant-numeric: tabular-nums;
}

.counter-at-limit {
  color: vz.color('destructive');
}
